INSERT INTO canonical_pod_scenarios SELECT * FROM json_populate_recordset(null::canonical_pod_scenarios, $tbr$[{"id":"talk-bollocks-4:SC01-S01","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":1,"global_order":1,"speaker":"TOM","english_text":"So this is Aran and Tom Talk Bollocks Part Four, we've got","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S02","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":2,"global_order":2,"speaker":"ARAN","english_text":"The future of education?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S03","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":3,"global_order":3,"speaker":"TOM","english_text":"Let's imagine some of the possibilities of what education could be, how your company, and maybe my company and the things that I'm doing, could be part of this imagined future, what that might look like.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S04","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":4,"global_order":4,"speaker":"TOM","english_text":"So, you start...","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S05","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":5,"global_order":5,"speaker":"ARAN","english_text":"The broad picture, I think is, that it's part of the whole thing, Game B, it isn't something that happens in isolation.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S06","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":6,"global_order":6,"speaker":"ARAN","english_text":"So, schooling is a complex adaptive system.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S07","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":7,"global_order":7,"speaker":"ARAN","english_text":"It's about going wider, but you also need to be getting UBI and increasing levels of UBI to free up people's time to be part of the whole thing.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S08","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":8,"global_order":8,"speaker":"ARAN","english_text":"And that's then what sort of blends into University-type existence and universities clearly have got dramatic changes to go through and that's, it's absolute reconstruction of a society to achieve something which is then capable of far greater things.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S09","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":9,"global_order":9,"speaker":"ARAN","english_text":"The end game really needs to be that you've got 7 billion connected and happy and enthusiastic minds, who will then be able to solve complicated problems","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S10","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":10,"global_order":10,"speaker":"TOM","english_text":"Do some cool shit.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S11","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":11,"global_order":11,"speaker":"ARAN","english_text":"Very, very quickly.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S12","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":12,"global_order":12,"speaker":"ARAN","english_text":"Get us through this sort of potential existence-bottleneck of the various sort of negative factors at the moment.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S13","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":13,"global_order":13,"speaker":"TOM","english_text":"Fundamentally that there isn't enough to go around - the scarcity mentality - which is provably wrong by all metrics...","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S14","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":14,"global_order":14,"speaker":"ARAN","english_text":"so yeah, you're trying to, you're trying to rewrite society, rebuild society...","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S15","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":15,"global_order":15,"speaker":"ARAN","english_text":"You're trying to network and give the joy of development and education and play to 7 billion people because we know that we've got the ability to feed and house them, we should just be doing that and to give them data and to give them energy, so we should just be doing that.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S16","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":16,"global_order":16,"speaker":"ARAN","english_text":"And of course there's some challenging political and power structure stuff that will probably need to happen, but you can also just build the alternatives.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S17","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":17,"global_order":17,"speaker":"ARAN","english_text":"And then if the alternatives are more successful - so thinking in terms of things like local currencies, so say you get to a stage - which I don't think is necessarily all that far away - where, anybody in Gwynedd who spends a couple of hours at school each day gets a certain amount of local currency for having done that.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S18","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":18,"global_order":18,"speaker":"ARAN","english_text":"So then you've got everybody in Gwynedd who's got any kind of desire in doing that, they're going to be doing it.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S19","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":19,"global_order":19,"speaker":"ARAN","english_text":"And 'Oh, look, they're being fed and clothed as a result of that as well.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S20","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":20,"global_order":20,"speaker":"ARAN","english_text":"Fantastic!'","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S21","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":21,"global_order":21,"speaker":"ARAN","english_text":"So it's possible that kind of system, that enough networked examples of that kind of system, then they remove the wealth that can be extracted by the power structure.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S22","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":22,"global_order":22,"speaker":"ARAN","english_text":"It's just not there anymore.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S23","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":23,"global_order":23,"speaker":"ARAN","english_text":"And then the power structure really is faced with a kind of an inevitable shriveling, and is faced with also, instead of a political enemy that it can imprison or criminalize, it's faced with a very distributed set of complex adaptive systems that it's incredibly hard to see 'where is the point where you shoot somebody to get them, to stop them all doing it?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S24","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":24,"global_order":24,"speaker":"ARAN","english_text":"It's very hard to deconstruct if that goes wide and distributed enough.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S25","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":25,"global_order":25,"speaker":"TOM","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S26","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":26,"global_order":26,"speaker":"TOM","english_text":"So what you need is - just starting it all off - you create the training wheels for this, universal, basic, local-currency as an alternative currency.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S27","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":27,"global_order":27,"speaker":"TOM","english_text":"And it's auto-poietic, self-perpetuating.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S28","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":28,"global_order":28,"speaker":"TOM","english_text":"So once you get it started, it can run and run.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S29","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":29,"global_order":29,"speaker":"ARAN","english_text":"And it's then a defensive wall on your resources - they can't be extracted because we're closed loops.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S30","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":30,"global_order":30,"speaker":"ARAN","english_text":"Yes.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S31","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":31,"global_order":31,"speaker":"TOM","english_text":"So, in essence - provided you've got access to oxygen, which most of us have...","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S32","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":32,"global_order":32,"speaker":"TOM","english_text":"There are some problems of scale where it may be difficult to access things like complete water supply, maybe electricity and those sorts of things - until you get to the stage where everyone is capable of generating enough electricity from light - which is not that far away.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S33","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":33,"global_order":33,"speaker":"TOM","english_text":"And then storing the electricity - and once you've got electricity...","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S34","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":34,"global_order":34,"speaker":"TOM","english_text":"probably water is still one that you need to work out a way to deal with...","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S35","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":35,"global_order":35,"speaker":"TOM","english_text":"but if you've got - presumably the ability to grow food within your community, get energy in your community and then have at least a level of compliance or 'agreements' shall we say between all the community members...","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S36","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":36,"global_order":36,"speaker":"TOM","english_text":"...then you're self-governing and that's brilliant.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S37","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":37,"global_order":37,"speaker":"TOM","english_text":"That's fantastic.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S38","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":38,"global_order":38,"speaker":"TOM","english_text":"And really the technology is there or thereabouts anyway, with vertical farms...","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S39","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":39,"global_order":39,"speaker":"TOM","english_text":"okay - you wouldn't be eating a lot of meat and all those sorts of things, but okay.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S40","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":40,"global_order":40,"speaker":"TOM","english_text":"I could see that.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S41","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":41,"global_order":41,"speaker":"TOM","english_text":"So then the question would be: How many of these things, can you do independently?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S42","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":42,"global_order":42,"speaker":"TOM","english_text":"How many of these things do you need to do together so that it all works?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S43","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":43,"global_order":43,"speaker":"TOM","english_text":"Because, this is the thing...","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S44","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":44,"global_order":44,"speaker":"TOM","english_text":"in a complex adaptive system: can you just start tinkering around with one and then they have a knock-on effect and it works well and all goes in your direction...","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S45","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":45,"global_order":45,"speaker":"TOM","english_text":"...","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S46","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":46,"global_order":46,"speaker":"TOM","english_text":"can you reinvent the laws of physics in such a way that then you end up producing atoms and molecules and stuff?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S47","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":47,"global_order":47,"speaker":"TOM","english_text":"Or do you have to work significantly on the pieces?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S48","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":48,"global_order":48,"speaker":"TOM","english_text":"And therefore the question is - if you have to work significantly on the pieces - do you have to redesign schooling and understanding and social media and energy and all these things?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S49","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":49,"global_order":49,"speaker":"TOM","english_text":"Do you have to do them all at once in this local community for it to work?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S50","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":50,"global_order":50,"speaker":"TOM","english_text":"No one knows the answers to these, but no, I wonder what your thoughts about - Where would you start?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S51","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":51,"global_order":51,"speaker":"TOM","english_text":"is it possible to start with one piece and if so, what would it be?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S52","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":52,"global_order":52,"speaker":"TOM","english_text":"And if it isn't possible, how would we start these multiple things?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S53","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":53,"global_order":53,"speaker":"TOM","english_text":"And how much is awareness?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S54","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":54,"global_order":54,"speaker":"TOM","english_text":"How much is legislation?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S55","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":55,"global_order":55,"speaker":"TOM","english_text":"How much is will of the people?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S56","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":56,"global_order":56,"speaker":"TOM","english_text":"How much is...","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S57","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":57,"global_order":57,"speaker":"TOM","english_text":"all those things?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S58","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":58,"global_order":58,"speaker":"TOM","english_text":"I don't know.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S59","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":59,"global_order":59,"speaker":"ARAN","english_text":"So my instinct, and what I'd like to give a crack at the whip is - that YES, you CAN start with one piece and it's the currency.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S60","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":60,"global_order":60,"speaker":"ARAN","english_text":"And that if you solve for the currency, that you then have a whole bunch of routes to influence that are resilient to existing power structure control.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S61","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":61,"global_order":61,"speaker":"ARAN","english_text":"And then at that stage, you can start saying: imagine we're here, and in this County we've solved the local currency thing.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S62","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":62,"global_order":62,"speaker":"ARAN","english_text":"So - and this is a lot of the sort of company stuff for me - we've needed to go and be competitive in the capitalist environment and to extract capital ourselves and to build our war chest, we then successfully used that to create a local currency here, which is now self-sustaining, no longer needs injection of stake capital","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S63","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":63,"global_order":63,"speaker":"TOM","english_text":"It's fungible, through us, for external dollars or English pounds or whatever","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC01-S64","pod_slug":"talk-bollocks-4","scene_number":1,"scene_label":"Chapter 1","scene_title":"The Future of Life, The Universe and Education","scene_subtitle":null,"difficulty":null,"sentence_number":64,"global_order":64,"speaker":"ARAN","english_text":"it is, or possibly that we've stopped that.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S01","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":1,"global_order":65,"speaker":"ARAN","english_text":"Now this isn't just, this is the element you're leading locally.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S02","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":2,"global_order":66,"speaker":"ARAN","english_text":"yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S03","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":3,"global_order":67,"speaker":"ARAN","english_text":"But nonetheless, because we imposed demurrage on it, it still requires a creation of fresh capital or fresh currency, but that's done by us.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S04","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":4,"global_order":68,"speaker":"ARAN","english_text":"So that then immediately is a very powerful control factor.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S05","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":5,"global_order":69,"speaker":"ARAN","english_text":"So we say straight off.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S06","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":6,"global_order":70,"speaker":"ARAN","english_text":"Okay, we start by saying actually it's just going to be UBI and here you all go, but then later on, we've pushed in the direction of some changes in the school system and we've got increasing numbers of adults able to be in, and now we say, okay, it's UBI but also you can get this extra stuff if you've been in school for a couple of hours, right?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S07","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":7,"global_order":71,"speaker":"ARAN","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S08","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":8,"global_order":72,"speaker":"TOM","english_text":"So the UBI might be a thousand, whatever, Gwynedd's a month and your extra, your LS, your learning supplement might be 500.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S09","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":9,"global_order":73,"speaker":"ARAN","english_text":"So, here are all these good things we'd like you to be doing...","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S10","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":10,"global_order":74,"speaker":"ARAN","english_text":"we'll pay you for all of them.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S11","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":11,"global_order":75,"speaker":"ARAN","english_text":"Because we don't, because we're creating this money - it's fiat currency.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S12","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":12,"global_order":76,"speaker":"TOM","english_text":"you're investing in the future of the country by investing in the people In the same way as that governments think that it's a good idea to educate everybody, so they invest, but they invest in educating people with what THEY think is important.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S13","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":13,"global_order":77,"speaker":"TOM","english_text":"Not what the individuals think is important.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S14","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":14,"global_order":78,"speaker":"ARAN","english_text":"But also what we're doing there - once you get to the stage where you've invested enough extracted wealth to get the system self-perpetuating, then at that stage, you've created your own power structure of a kind, because what you're then doing is you are then creating new currency each month to make up for the fact that you have demurrage.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S15","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":15,"global_order":79,"speaker":"ARAN","english_text":"So you have that power.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S16","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":16,"global_order":80,"speaker":"ARAN","english_text":"It's like a magic wand.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S17","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":17,"global_order":81,"speaker":"ARAN","english_text":"It's like the banks!!!","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S18","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":18,"global_order":82,"speaker":"ARAN","english_text":"The banks don't have to earn more money to be able to give you a mortgage.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S19","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":19,"global_order":83,"speaker":"ARAN","english_text":"You just say: 'I'd like a mortgage' they decide that you're right for it.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S20","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":20,"global_order":84,"speaker":"ARAN","english_text":"And they invent that money.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S21","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":21,"global_order":85,"speaker":"ARAN","english_text":"This money now exists as a loan.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S22","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":22,"global_order":86,"speaker":"ARAN","english_text":"It didn't exist previously.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S23","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":23,"global_order":87,"speaker":"ARAN","english_text":"We don't have to take it out of another bank or anything.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S24","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":24,"global_order":88,"speaker":"TOM","english_text":"Nope.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S25","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":25,"global_order":89,"speaker":"ARAN","english_text":"And that obviously creates an incredibly strong power structure there for them...","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S26","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":26,"global_order":90,"speaker":"ARAN","english_text":"but what we're doing then is creating an alternative power structure.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S27","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":27,"global_order":91,"speaker":"ARAN","english_text":"We're creating the currency on a monthly basis.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S28","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":28,"global_order":92,"speaker":"ARAN","english_text":"So we can then start to, put terms and conditions on that.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S29","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":29,"global_order":93,"speaker":"ARAN","english_text":"So we've got UBI because that's clearly the right thing to be doing.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S30","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":30,"global_order":94,"speaker":"ARAN","english_text":"But then we're saying: here are a set of things that we consider to be contributions to the community and we will therefore be giving extra currency for these contributions to the community.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S31","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":31,"global_order":95,"speaker":"ARAN","english_text":"And then also, you've got the, you've taken control of the levers of communication...","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S32","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":32,"global_order":96,"speaker":"ARAN","english_text":"because if people want currency from you, then there is a communicative channel there.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S33","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":33,"global_order":97,"speaker":"ARAN","english_text":"So you can then - in a single month - make sure that everybody in this County knows about the latest, good idea for how we make local energy work a little bit better.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S34","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":34,"global_order":98,"speaker":"ARAN","english_text":"And we need, a few dozen volunteers and everybody in the County has heard about it.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S35","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":35,"global_order":99,"speaker":"ARAN","english_text":"So we find a few dozen volunteers, but also we can give them a currency for that.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S36","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":36,"global_order":100,"speaker":"ARAN","english_text":"so every single good idea you have, every single good idea that the community generates, you then get a kind of filtering process.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S37","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":37,"global_order":101,"speaker":"ARAN","english_text":"And the ones which bubble up to the top, and are popular enough, and get the kind of sign off, then they're put back to the community as: here's a thing, here's a new, good idea, we want to do this, there's currency available for doing it.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S38","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":38,"global_order":102,"speaker":"TOM","english_text":"Yes!!!","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S39","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":39,"global_order":103,"speaker":"TOM","english_text":"I'll take you back a couple of years when I was thinking about this a lot.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S40","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":40,"global_order":104,"speaker":"TOM","english_text":"And there's a think tank in Cambridge that I was working with - part of the university actually - we thought if we solve for energy first, cause if you solve for energy, then really you can solve for pretty much everything else.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S41","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":41,"global_order":105,"speaker":"TOM","english_text":"there is a fixed number of atoms on the planet.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S42","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":42,"global_order":106,"speaker":"TOM","english_text":"We're not losing atoms of water, so we're not running out of water.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S43","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":43,"global_order":107,"speaker":"TOM","english_text":"The only thing we might be running out of or might not have access to, is the ability to purify, clean, regenerate that water: recombine hydrogen / oxygen atoms to make water.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S44","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":44,"global_order":108,"speaker":"TOM","english_text":"So we're not, we're not obviously not running out.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S45","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":45,"global_order":109,"speaker":"TOM","english_text":"There's an atom level, then there's the energy level.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S46","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":46,"global_order":110,"speaker":"TOM","english_text":"Now energy is it's not unlimited, but your flux is significant.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S47","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":47,"global_order":111,"speaker":"TOM","english_text":"The daily flux from the sun is significant.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S48","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":48,"global_order":112,"speaker":"TOM","english_text":"So if we could solve for that and make energy as abundant as music or oxygen or whatever, then, provided we built the awareness and all that good stuff then all the other problems would be sorted as well.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S49","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":49,"global_order":113,"speaker":"TOM","english_text":"but interestingly you're saying: we don't even need to wait for that because we could live in the existing energy- metered situation, the current way we deal with the world in terms of the energy - could easily be, interacted with and solved in terms of the kind of the extraction of resources by just producing local currency to work.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC02-S50","pod_slug":"talk-bollocks-4","scene_number":2,"scene_label":"Chapter 2","scene_title":"Local Currency Universal Basic Income (UBI)","scene_subtitle":null,"difficulty":null,"sentence_number":50,"global_order":114,"speaker":"TOM","english_text":"yeah, I think.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S01","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":1,"global_order":115,"speaker":"ARAN","english_text":"So one of the things there, and this for me is - the sort of the classic activist dilemma - What you were just talking about there sounds fantastic: a crew of bright people in Cambridge with some university involvement, thinking how do we solve for energy?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S02","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":2,"global_order":116,"speaker":"ARAN","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S03","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":3,"global_order":117,"speaker":"ARAN","english_text":"Brilliant.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S04","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":4,"global_order":118,"speaker":"ARAN","english_text":"And what's happened to that group now?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S05","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":5,"global_order":119,"speaker":"ARAN","english_text":"You said you were doing it a couple of years ago?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S06","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":6,"global_order":120,"speaker":"TOM","english_text":"So we started the project and the initial kickoff was, we did a design sprint on it, which was: okay, let's explore all the pieces that we would need to think about in order to make it work: and we said, let's start as a 10 year project.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S07","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":7,"global_order":121,"speaker":"TOM","english_text":"So it's gone a little bit cold jokingly.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S08","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":8,"global_order":122,"speaker":"TOM","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S09","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":9,"global_order":123,"speaker":"TOM","english_text":"Because...","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S10","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":10,"global_order":124,"speaker":"ARAN","english_text":"how many people were involved?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S11","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":11,"global_order":125,"speaker":"TOM","english_text":"It was, my college.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S12","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":12,"global_order":126,"speaker":"TOM","english_text":"There was about 15 people, university think-tank, couple of interesting players, couple of startup companies.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S13","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":13,"global_order":127,"speaker":"TOM","english_text":"The problem is the model that they're all bringing to it is still, a capitalist sort of extractive model on this and thinking: We've got to find a way to make it cheap enough for everybody.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S14","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":14,"global_order":128,"speaker":"TOM","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S15","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":15,"global_order":129,"speaker":"TOM","english_text":"Which if you solve for local currency.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S16","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":16,"global_order":130,"speaker":"TOM","english_text":"Exactly.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S17","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":17,"global_order":131,"speaker":"ARAN","english_text":"But also, what you said that, 15 people involved, brilliant idea, a thing that absolutely needs to happen, you're in Cambridge.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S18","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":18,"global_order":132,"speaker":"ARAN","english_text":"I don't know what the population Cambridge is, but it's hefty - 150,000 people maybe?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S19","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":19,"global_order":133,"speaker":"ARAN","english_text":"So the problem we're actually facing is this classic thing that we just don't have many people who are time rich.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S20","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":20,"global_order":134,"speaker":"ARAN","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S21","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":21,"global_order":135,"speaker":"ARAN","english_text":"They're just not out there because they're caught in the capitalist structure.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S22","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":22,"global_order":136,"speaker":"TOM","english_text":"Correct.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S23","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":23,"global_order":137,"speaker":"ARAN","english_text":"So we've got a small number of people who are time rich and can do it.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S24","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":24,"global_order":138,"speaker":"ARAN","english_text":"We've got a slightly larger number of people who are time poor, but will volunteer anyway.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S25","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":25,"global_order":139,"speaker":"ARAN","english_text":"But they're very likely to get burned out at some point.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S26","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":26,"global_order":140,"speaker":"ARAN","english_text":"10 year project?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S27","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":27,"global_order":141,"speaker":"ARAN","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S28","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":28,"global_order":142,"speaker":"ARAN","english_text":"Oh, my God!","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S29","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":29,"global_order":143,"speaker":"ARAN","english_text":"That's 10% of my life, and I've got to keep doing this and I've got the kids did all that kind of stuff.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S30","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":30,"global_order":144,"speaker":"ARAN","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S31","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":31,"global_order":145,"speaker":"ARAN","english_text":"If you turn it on its head, if you solve for a Solve for the things that are consuming people's resources at the moment.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S32","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":32,"global_order":146,"speaker":"ARAN","english_text":"Which is currency, which is lack of currency.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S33","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":33,"global_order":147,"speaker":"TOM","english_text":"Exactly.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S34","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":34,"global_order":148,"speaker":"ARAN","english_text":"And needing to work to get some yeah","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S35","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":35,"global_order":149,"speaker":"TOM","english_text":"so what you're saying really is the most important thing to leverage is people's metaphysical powers, but their metaphysical powers are not available because they're spending their time physically burning those up because they're actually having to work for currency.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S36","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":36,"global_order":150,"speaker":"TOM","english_text":"So currency is the great leverage.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S37","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":37,"global_order":151,"speaker":"ARAN","english_text":"So, if we solve currency for 80,000 people in Gwynedd, so less people than in Cambridge, but it's a fair old chunk.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S38","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":38,"global_order":152,"speaker":"ARAN","english_text":"We solve for currency there and by the way - we've got this project for energy, and you can help, and maybe we get 5,000 people saying yes.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S39","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":39,"global_order":153,"speaker":"ARAN","english_text":"So you've got 15 people trying to achieve a project, or you've got 5,000 people trying to achieve a project, which one has got the better shot?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S40","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":40,"global_order":154,"speaker":"TOM","english_text":"And you would solve for energy by making a capture of the sun's flux - make it happen at a local level, cause what you really want to be doing is saying: and you can do this anywhere in the world.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S41","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":41,"global_order":155,"speaker":"TOM","english_text":"Distributed.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S42","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":42,"global_order":156,"speaker":"ARAN","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S43","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":43,"global_order":157,"speaker":"ARAN","english_text":"Distributed.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S44","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":44,"global_order":158,"speaker":"ARAN","english_text":"Have you seen some of the stuff from one of Peter Diamandis' email but there was one that came out a while ago, which was they'd found four or five companies that had seed funding from investment funds - so people who are not wanting to throw their money away - for carbon capture.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S45","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":45,"global_order":159,"speaker":"ARAN","english_text":"Yeah, local carbon capture - local portable carbon capture.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S46","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":46,"global_order":160,"speaker":"ARAN","english_text":"So basically you set your little machine up, it collects carbon and it gives you a brick!","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S47","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":47,"global_order":161,"speaker":"ARAN","english_text":"And suddenly you're dealing with global warming, but you're also saying we just solved a materials shortage in rural areas!","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S48","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":48,"global_order":162,"speaker":"ARAN","english_text":"See, I think I read that and I thought this is the April the first edition!","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S49","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":49,"global_order":163,"speaker":"ARAN","english_text":"And then it wasn't!!!","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S50","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":50,"global_order":164,"speaker":"TOM","english_text":"I don't think the technological pieces are the challenge...","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S51","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":51,"global_order":165,"speaker":"TOM","english_text":"solar cells are now something like six times as efficient as chlorophyll: capturing solar energy and turning into useful energy!","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S52","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":52,"global_order":166,"speaker":"TOM","english_text":"Because they don't have to keep a plant alive!","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S53","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":53,"global_order":167,"speaker":"TOM","english_text":"They don't have to do all those things - so they're actually making energy available.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S54","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":54,"global_order":168,"speaker":"TOM","english_text":"So humans are pretty neat.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S55","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":55,"global_order":169,"speaker":"TOM","english_text":"The question would be: can you make sure that you can preserve the technology for the greater life to all?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S56","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":56,"global_order":170,"speaker":"TOM","english_text":"Because if I'm an existing power structure, I'm going to fight really hard with all my significant wealth to hold onto that.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S57","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":57,"global_order":171,"speaker":"TOM","english_text":"And I'm going to fight significantly to make awareness, be so low in society that realize this isn't possible, to perhaps bury these technologies or get so much legislative power on these technologies so when they come into play at some point in the future, I've had time to build in the metering system, which can then meter the solar power and control to prevent individual local capture.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S58","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":58,"global_order":172,"speaker":"TOM","english_text":"Yeah - cause if you're a power structure...","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S59","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":59,"global_order":173,"speaker":"TOM","english_text":"not everyone has access to oil, so the oil is in one place.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S60","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":60,"global_order":174,"speaker":"TOM","english_text":"We can then deliver it to anybody as electricity and make money out of it.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S61","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":61,"global_order":175,"speaker":"TOM","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S62","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":62,"global_order":176,"speaker":"TOM","english_text":"But so you solve for currency","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S63","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":63,"global_order":177,"speaker":"ARAN","english_text":"if we're providing currency to everybody in Gwynedd and Exxon want to stop them from finding out about something, they're stuffed.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S64","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":64,"global_order":178,"speaker":"ARAN","english_text":"They can't.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S65","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":65,"global_order":179,"speaker":"ARAN","english_text":"If we want them to find out about it, they're going to find out about it.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S66","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":66,"global_order":180,"speaker":"ARAN","english_text":"So you start to build that kind of immunization against the power structures.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S67","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":67,"global_order":181,"speaker":"ARAN","english_text":"And then you've probably got a really interesting battle in terms of the capacity of large players to respond with IP attacks to new ideas.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S68","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":68,"global_order":182,"speaker":"ARAN","english_text":"So I read something very interesting about a guy who was at an IP meeting somewhere, conference somewhere.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S69","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":69,"global_order":183,"speaker":"ARAN","english_text":"And he had a good idea about graphene, something like that.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S70","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":70,"global_order":184,"speaker":"ARAN","english_text":"And he saw some representatives of a fairly large company there and went to have a chat and said: 'look, I think I'm onto something here, do you want to invest and help me get there faster?'","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S71","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":71,"global_order":185,"speaker":"ARAN","english_text":"what they said: 'yeah, no thanks, because we think it still looks a little bit high risk, but we've seen that you're working on it and we're paying attention and we really hope you solve it' and he said: 'yeah, but if I solve it and you haven't come on, then I'm not going to be giving it to you' and they said: 'no, you're going to take out some kind of an IP thing on it yeah?'","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S72","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":72,"global_order":186,"speaker":"ARAN","english_text":"and he said, 'yeah, exactly' and they said: 'yeah, and we employ over a thousand IP lawyers and we are then going to ring fence your IP with IP for all the possible use cases.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S73","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":73,"global_order":187,"speaker":"ARAN","english_text":"So you won't be able to use it and then you license it to us because that's the only way you'll get any use out of it.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S74","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":74,"global_order":188,"speaker":"ARAN","english_text":"And sorry.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S75","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":75,"global_order":189,"speaker":"ARAN","english_text":"That's how it works.'","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S76","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":76,"global_order":190,"speaker":"ARAN","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S77","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":77,"global_order":191,"speaker":"ARAN","english_text":"So it's really, IP is really interesting as a defensive wall for large power structures.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S78","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":78,"global_order":192,"speaker":"ARAN","english_text":"It's a disaster IP, absolute disaster.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S79","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":79,"global_order":193,"speaker":"ARAN","english_text":"Absolutely.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S80","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":80,"global_order":194,"speaker":"ARAN","english_text":"It's possibly the worst thing you can think of: I'm going to try and develop something which will be hugely beneficial to humans and then try and prevent humans from using it.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S81","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":81,"global_order":195,"speaker":"ARAN","english_text":"Yeah, cause you want to extract capital just because there isn't a universal, basic income...","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S82","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":82,"global_order":196,"speaker":"ARAN","english_text":"In parallel with this conversation, I've just had an email from people who are considering investing in us at the moment, saying we do want details of your IP cause we really need to know there's IP in order to invest!","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S83","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":83,"global_order":197,"speaker":"ARAN","english_text":"I'm busy saying, yeah, we've got IP loads of it.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S84","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":84,"global_order":198,"speaker":"ARAN","english_text":"Cause we do!","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S85","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":85,"global_order":199,"speaker":"TOM","english_text":"We're at horizon one, right?","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S86","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":86,"global_order":200,"speaker":"TOM","english_text":"We are where we are now.","author_notes":null,"created_at":"2026-10-20 22:40:23.655562+00","updated_at":"2026-10-20 22:40:23.655562+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S87","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":87,"global_order":201,"speaker":"TOM","english_text":"And we live where we do now and we have to start where we are.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S88","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":88,"global_order":202,"speaker":"TOM","english_text":"So - I would like to transcend my physical form, but I still have urges.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S89","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":89,"global_order":203,"speaker":"TOM","english_text":"I still need to eat and poo and that sort of stuff.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S90","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":90,"global_order":204,"speaker":"TOM","english_text":"okay, I would like to just think of ideas and not worry about anything else, but these sorts of things, yeah - they're going to persist for a little time.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC03-S91","pod_slug":"talk-bollocks-4","scene_number":3,"scene_label":"Chapter 3","scene_title":"The Activist's Dilemma","scene_subtitle":null,"difficulty":null,"sentence_number":91,"global_order":205,"speaker":"TOM","english_text":"The trick is making sure that all the things that we are doing are diminishing the reliance on the current status quo and increasing our chances of moving towards the ultimate goal.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S01","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":1,"global_order":206,"speaker":"TOM","english_text":"So, if your business model is designed to then get people better at learning and to generate money which you can plough into local communities in a regenerative way because you're investing in a currency...","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S02","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":2,"global_order":207,"speaker":"TOM","english_text":"that'd be massive.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S03","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":3,"global_order":208,"speaker":"TOM","english_text":"There'd be so much political will to not let you do that though.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S04","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":4,"global_order":209,"speaker":"TOM","english_text":"So the question would be, would you do it subtly because you don't even need an actual currency.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S05","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":5,"global_order":210,"speaker":"TOM","english_text":"You just need cards that just have a ledger system that just record transactions.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S06","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":6,"global_order":211,"speaker":"ARAN","english_text":"They're really stuffed on that now, because as long as you've been reasonably thoughtful about how you do it, then they can only criminalize you if they're also going to criminalize air miles and Amex points and then you've got conflicting power structures going 'no!","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S07","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":7,"global_order":212,"speaker":"ARAN","english_text":"Bugger off!'","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S08","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":8,"global_order":213,"speaker":"ARAN","english_text":"I think it's very close to a point where it's extremely hard to stop these kinds of things politically.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S09","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":9,"global_order":214,"speaker":"ARAN","english_text":"I sort of think that politics, as we know it is actually in the process of ceasing to exist.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S10","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":10,"global_order":215,"speaker":"ARAN","english_text":"Politics is already dead, it just doesn't know it yet.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S11","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":11,"global_order":216,"speaker":"ARAN","english_text":"And it just hasn't realized itself yet.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S12","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":12,"global_order":217,"speaker":"TOM","english_text":"Yeah, it's already died.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S13","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":13,"global_order":218,"speaker":"TOM","english_text":"I've been saying this for a little while: Politics is already irrelevant.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S14","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":14,"global_order":219,"speaker":"TOM","english_text":"It's already dead, it just doesn't know it yet.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S15","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":15,"global_order":220,"speaker":"TOM","english_text":"In terms of its influence, do we genuinely think in the same way that we might have thought when we grew up, that politicians and the leaders of various countries as elected representatives are capable of making wise decisions?","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S16","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":16,"global_order":221,"speaker":"TOM","english_text":"we don't really think that anymore, even if we thought they had the correct intentions, which were questionable as well, we don't think that they've got the capacity anymore.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S17","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":17,"global_order":222,"speaker":"TOM","english_text":"The world is way too complex!","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S18","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":18,"global_order":223,"speaker":"TOM","english_text":"And most people are so invested in the status quo...","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S19","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":19,"global_order":224,"speaker":"TOM","english_text":"democrats or Republicans in America.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S20","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":20,"global_order":225,"speaker":"TOM","english_text":"It's really interesting - basically, there's very little difference, really, when you think about the preservation of the power structures.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S21","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":21,"global_order":226,"speaker":"TOM","english_text":"How can America with its 300+ million people have produced Biden as the best candidate to stand against Trump?","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S22","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":22,"global_order":227,"speaker":"TOM","english_text":"Really!","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S23","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":23,"global_order":228,"speaker":"TOM","english_text":"That's a genuine question: how is that possible?","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S24","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":24,"global_order":229,"speaker":"TOM","english_text":"the only argument for that would be, it wasn't really in anyone's interest to really change things significantly.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S25","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":25,"global_order":230,"speaker":"TOM","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S26","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":26,"global_order":231,"speaker":"TOM","english_text":"yeah, of course - black lives matter, of course - racism of course - wages for Americans of course - stopping the IP leak to China all those things are relatively interesting to Americans, but in general, it seems that really, in terms of big business, big pharma, global food supply, agriculture or factory farming, all these things well, how much difference is there between Republicans and Democrats, really?","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S27","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":27,"global_order":232,"speaker":"TOM","english_text":"It's going to be really interesting.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S28","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":28,"global_order":233,"speaker":"TOM","english_text":"Okay.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S29","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":29,"global_order":234,"speaker":"ARAN","english_text":"Conceptually speaking, there are reasons to think that there are possible ignition events then to get to those ignition events you need either time or money or in some instances both time and money.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S30","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":30,"global_order":235,"speaker":"ARAN","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S31","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":31,"global_order":236,"speaker":"ARAN","english_text":"So really what we're trying to do, with what on the face of it is a moderately traditional company.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S32","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":32,"global_order":237,"speaker":"ARAN","english_text":"We're a language training company.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S33","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":33,"global_order":238,"speaker":"ARAN","english_text":"There are loads of those.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S34","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":34,"global_order":239,"speaker":"ARAN","english_text":"and okay we would go and make the case that we've got some qualitatively different things going on and that we've therefore got opportunities to scale, which are not shared by many of our competitors or many of our current competitors.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S35","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":35,"global_order":240,"speaker":"ARAN","english_text":"So all that kind of stuff, but all of that really is just icing on a very traditional cake.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S36","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":36,"global_order":241,"speaker":"ARAN","english_text":"And the reason why it feels worth doing is because we can see that it's got this combination of a capacity for large scale extraction of wealth - which is not predicated on impoverishing anybody else: so if we're saying, it's a tenner a month, then we're providing extremely good value for that tenner a month.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S37","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":37,"global_order":242,"speaker":"ARAN","english_text":"We're not trying to lock people into ways in which it's then very difficult for them to stop giving us any of that kind of stuff.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S38","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":38,"global_order":243,"speaker":"ARAN","english_text":"So it's a pretty, morally acceptable formula.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S39","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":39,"global_order":244,"speaker":"ARAN","english_text":"It's not based on worker exploitation, it's not based on consumer exploitation.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S40","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":40,"global_order":245,"speaker":"ARAN","english_text":"It's based on creating very high value, which has got a lot of potential positive impact that we can build further on for a reasonable price, but clearly because it's scalable, it's got the capacity to extract very large amounts of capital.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S41","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":41,"global_order":246,"speaker":"ARAN","english_text":"That extraction device is then where we get the capacity to start freeing up people's time.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S42","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":42,"global_order":247,"speaker":"TOM","english_text":"Re-routing the capital from individuals who are paying for some learning into, projects to benefit","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S43","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":43,"global_order":248,"speaker":"ARAN","english_text":"ignition events.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S44","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":44,"global_order":249,"speaker":"ARAN","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S45","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":45,"global_order":250,"speaker":"ARAN","english_text":"We've already freed up quite a few: the 10 people who work full time for us, none of them do more than about 20 hours a week, but they get a full time salary for that.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S46","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":46,"global_order":251,"speaker":"ARAN","english_text":"So we're going to continue to do that.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S47","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":47,"global_order":252,"speaker":"ARAN","english_text":"We're going to employ as many people as we can and create that kind of half and half thing, but then also you fund and you drive for an ignition event of a currency in Gwynedd that then potentially frees up the time of tens of thousands of people.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S48","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":48,"global_order":253,"speaker":"ARAN","english_text":"And then at that stage, you've got a potential volunteer army or currency-driven army that you're paying with this currency that you're able to create freely to do all the sorts of the subsequent ignition events, I think probably then you get to a tipping point very quickly, but you have it.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S49","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":49,"global_order":254,"speaker":"ARAN","english_text":"You have an initial ignition event which creates time...","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S50","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":50,"global_order":255,"speaker":"ARAN","english_text":"and that then inevitably creates subsequent ignition events.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S51","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":51,"global_order":256,"speaker":"ARAN","english_text":"and quickly it looks like a cascade that becomes impossible to stop.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S52","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":52,"global_order":257,"speaker":"TOM","english_text":"And you're not even trying to get the agreement between all the players in Gwynedd, before you start, you're just actually saying: 'listen, if you do this, we will pay you at the end of the month, 700 tokens or whatever the people have used to buy your stuff, we'll exchange it for actual cash.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S53","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":53,"global_order":258,"speaker":"TOM","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC04-S54","pod_slug":"talk-bollocks-4","scene_number":4,"scene_label":"Chapter 4","scene_title":"Business Models To Improve Learning & Generate Money","scene_subtitle":null,"difficulty":null,"sentence_number":54,"global_order":259,"speaker":"TOM","english_text":"And that would happen at the end of the month?","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S01","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":1,"global_order":260,"speaker":"TOM","english_text":"Presumably, they would be able to use those tokens in the interim period.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S02","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":2,"global_order":261,"speaker":"TOM","english_text":"Yep.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S03","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":3,"global_order":262,"speaker":"TOM","english_text":"As often as they wanted to, but then when it gets to the end of the month, you guarantee or whatever...","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S04","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":4,"global_order":263,"speaker":"ARAN","english_text":"the process of moving that towards self-perpetuation is really interesting because you've got all sorts of really simple little levers in there.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S05","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":5,"global_order":264,"speaker":"ARAN","english_text":"So you start off by saying: ' we'll refund you in full - if you can't spend it, if you've got it, before it then gets its hit in value, we'll refund you in full' so you get people going 'well, I haven't been able to spend it, please refund me in full' and then as the network starts to increase - you don't need to pull the plug on it, but you can say, you know what?","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S06","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":6,"global_order":265,"speaker":"ARAN","english_text":"this is working really well and actually we know you've had opportunity to use it.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S07","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":7,"global_order":266,"speaker":"ARAN","english_text":"So we'll refund you at 90% now.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S08","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":8,"global_order":267,"speaker":"ARAN","english_text":"if you can spend it yourself, that's going to be better for you than getting the 90% back from us.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S09","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":9,"global_order":268,"speaker":"ARAN","english_text":"Then over time, you just, you drop that down and it becomes less and then eventually it just becomes a kind of an understood thing that, 'okay, there was an end - the parcel went round and I didn't actually get to spend this, but...","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S10","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":10,"global_order":269,"speaker":"ARAN","english_text":"I'd spent several others that I got and I don't mind the fact that now I have fewer.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S11","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":11,"global_order":270,"speaker":"TOM","english_text":"Just saying, so let's say you've got a hundred thousand and you're giving them a thousand a month, so you need a hundred million a month if you're going to give them a universal basic income - in real money and not spend it at all.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S12","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":12,"global_order":271,"speaker":"TOM","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S13","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":13,"global_order":272,"speaker":"TOM","english_text":"So you need a hundred million a month, which actually is a billion a year of profit.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S14","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":14,"global_order":273,"speaker":"TOM","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S15","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":15,"global_order":274,"speaker":"TOM","english_text":"Assuming you get none of it back.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S16","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":16,"global_order":275,"speaker":"TOM","english_text":"A) that's achievable anyway.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S17","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":17,"global_order":276,"speaker":"TOM","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S18","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":18,"global_order":277,"speaker":"TOM","english_text":"There are companies that make a billion a year profit.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S19","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":19,"global_order":278,"speaker":"TOM","english_text":"Yep","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S20","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":20,"global_order":279,"speaker":"ARAN","english_text":"But you also, you don't have to start with the entire population","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S21","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":21,"global_order":280,"speaker":"TOM","english_text":"you also don't have to start with the universal basic income part of it either, you could just start with the currency and the agreements,","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S22","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":22,"global_order":281,"speaker":"ARAN","english_text":"A basic income, but not universal because we don't have the funds yet, but we'll create this.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S23","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":23,"global_order":282,"speaker":"ARAN","english_text":"If we get this net a learner income.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S24","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":24,"global_order":283,"speaker":"ARAN","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S25","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":25,"global_order":284,"speaker":"ARAN","english_text":"So when we get to say, if we say we're going to do it for a thousand people, and we're going to give you a hundred pounds a month, and it's, we've got sort of 10 separate places where you can spend that, then we've got that thing happening.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S26","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":26,"global_order":285,"speaker":"ARAN","english_text":"And initially that's costing us.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S27","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":27,"global_order":286,"speaker":"ARAN","english_text":"It's costing us a hundred thousand a month.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S28","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":28,"global_order":287,"speaker":"ARAN","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S29","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":29,"global_order":288,"speaker":"ARAN","english_text":"But they're starting to do multiple spends, so then we're gradually dropping the amount that we're refunding.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S30","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":30,"global_order":289,"speaker":"ARAN","english_text":"So eventually we get down to, as we drop the amount we refund, we can add people into the network.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S31","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":31,"global_order":290,"speaker":"ARAN","english_text":"So we're just dropping, adding, dropping, adding.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S32","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":32,"global_order":291,"speaker":"ARAN","english_text":"So we're putting in about a hundred thousand, 200,000 a month but then eventually that itself will get to a stage where, okay, now we've got to the point where we're not putting any stake capital in, we're just saying where the money gets created and now we're adding people to that loop and adding more and more, and that's how you then go up to actually, we can now do it for all of you.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S33","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":33,"global_order":292,"speaker":"ARAN","english_text":"And the amount you're getting can be going up and all that kind of stuff.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S34","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":34,"global_order":293,"speaker":"ARAN","english_text":"So it's not about a billion a year to do it as a, just one-stop thing: we are now paying a thousand pounds to everybody in Gwynedd.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S35","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":35,"global_order":294,"speaker":"ARAN","english_text":"but you absolutely don't have to start there.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S36","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":36,"global_order":295,"speaker":"ARAN","english_text":"You start small.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S37","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":37,"global_order":296,"speaker":"ARAN","english_text":"And then you look for self-perpetuation and then you expand from there.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S38","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":38,"global_order":297,"speaker":"TOM","english_text":"And you would start with possibly making a judgment call: if we could find a hundred great people a month that we could pay a thousand pounds to, let's say you're allocating a million a year for the project...","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S39","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":39,"global_order":298,"speaker":"TOM","english_text":"could we start off with a hundred people that we're paying a thousand a month to, because then we've got, we're going to have people who are maybe the coders and the designers and the scientists and those sorts of things.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S40","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":40,"global_order":299,"speaker":"TOM","english_text":"Wow - what if we could do something like that...","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S41","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":41,"global_order":300,"speaker":"TOM","english_text":"So...","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S42","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":42,"global_order":301,"speaker":"TOM","english_text":"presumably it could cost way less than the budget that you've allocated.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S43","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":43,"global_order":302,"speaker":"ARAN","english_text":"If you're saying to everybody: 'if you're stuck at the end of the month, when the demurrage is about to hit you, we will then repay you' then it's like atoms, isn't it.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S44","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":44,"global_order":303,"speaker":"ARAN","english_text":"You've created this amount of currency - it's moved around a lot, and then at the end of the month, everybody wants you to pay it back.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S45","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":45,"global_order":304,"speaker":"ARAN","english_text":"So actually probably, as soon as you got to the stage where you've got a network of, a dozen or so options, you're saying, 'look, here it is and we're giving it to you - you've got to say to the shops: if you're stuck with any, at the end of the month, we'll pay you back to the people: if you're stuck with any, at the end of the month, too bad, you didn't spend it.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S46","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":46,"global_order":305,"speaker":"ARAN","english_text":"It's your fault.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S47","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":47,"global_order":306,"speaker":"ARAN","english_text":"It's going to hit demurrage.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S48","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":48,"global_order":307,"speaker":"ARAN","english_text":"So you're only paying the shops back.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S49","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":49,"global_order":308,"speaker":"ARAN","english_text":"So you're not going to be - neatly at the end of the month.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S50","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":50,"global_order":309,"speaker":"ARAN","english_text":"All the money is in all the shops...","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S51","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":51,"global_order":310,"speaker":"ARAN","english_text":"you're maybe only 80%, 70, 60, 50%.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S52","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":52,"global_order":311,"speaker":"ARAN","english_text":"But then you start saying to the shops, 'okay, look, this is working and it's working for you and you're managing to spend a lot of this, we're now only going to give you 50% back at the end of the month, so make an effort to spend it.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S53","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":53,"global_order":312,"speaker":"ARAN","english_text":"and step-by-step the model there, I think, is capable of being a seed that grows and then eventually gets to a tipping point.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S54","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":54,"global_order":313,"speaker":"TOM","english_text":"What do you need in terms of merchants and farmers and people like that?","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S55","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":55,"global_order":314,"speaker":"ARAN","english_text":"Food is the start Some kind of a deal on council tax.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S56","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":56,"global_order":315,"speaker":"ARAN","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S57","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":57,"global_order":316,"speaker":"ARAN","english_text":"Some kind of a deal on rent.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S58","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":58,"global_order":317,"speaker":"ARAN","english_text":"And then you're very top of mind.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S59","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":59,"global_order":318,"speaker":"ARAN","english_text":"and council tax is an interesting one, because if you can say, look, this solves for council tax, actually, the councils are all just bloody strapped for cash.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S60","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":60,"global_order":319,"speaker":"ARAN","english_text":"So you can say to them, 'look, we will initially give you a slightly higher level of funding and we will then expect you to start making some levels of payment in the currency and actually that's going to save you money' Then you can loop into a situation where you start to get the council is saving money by paying people partly in state currency, partly in local currency and then accepting local currency.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S61","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":61,"global_order":320,"speaker":"TOM","english_text":"You want people to be paying wages in the local currency","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S62","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":62,"global_order":321,"speaker":"ARAN","english_text":"and you initially say: 'accept the local currency, and we'll pay you back' but then over time you say: 'accept the local currency and help set up the networks' And that's then going to drive you into purchasing local much more because most of them bloody don't yeah, I think when we get to the stage where we can stick a million quid a month into it, we've got a real goer, which looks a lot like teaching English to China!","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S63","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":63,"global_order":322,"speaker":"TOM","english_text":"If you think that there are 1.4 billion Chinese, nearly all of them.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S64","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":64,"global_order":323,"speaker":"TOM","english_text":"So say 1.2 billion, either.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S65","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":65,"global_order":324,"speaker":"TOM","english_text":"Have learned English or would appreciate learning English.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S66","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":66,"global_order":325,"speaker":"TOM","english_text":"And then he said, okay, let's take 1% of those.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S67","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":67,"global_order":326,"speaker":"TOM","english_text":"So 1.2 billion, that's still a hundred.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S68","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":68,"global_order":327,"speaker":"TOM","english_text":"And, it's still 12 million and think get 12 million people paying, 10 quid a month.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S69","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":69,"global_order":328,"speaker":"TOM","english_text":"So there's that?","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S70","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":70,"global_order":329,"speaker":"TOM","english_text":"Yeah, it's like 220, 120 million.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S71","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":71,"global_order":330,"speaker":"TOM","english_text":"So 120 million a month.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S72","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":72,"global_order":331,"speaker":"TOM","english_text":"And you've got to say, you've got to make, okay.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC05-S73","pod_slug":"talk-bollocks-4","scene_number":5,"scene_label":"Chapter 5","scene_title":"How Would The Local Currency Actually Work?","scene_subtitle":null,"difficulty":null,"sentence_number":73,"global_order":332,"speaker":"TOM","english_text":"So you've got to make profit on that, then say, if we were a 1% profit margin to put in this...","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S01","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":1,"global_order":333,"speaker":"ARAN","english_text":"but I also think that an ignition event on local currency is where we're trying to get to, is where we are going to get to and I believe we'll, we will get there, but, I think that's not the very first thing you try to do.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S02","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":2,"global_order":334,"speaker":"ARAN","english_text":"The very first thing you try to do is make a play for the education layer.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S03","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":3,"global_order":335,"speaker":"ARAN","english_text":"So you're taking the money that comes in.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S04","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":4,"global_order":336,"speaker":"ARAN","english_text":"You're investing it in rolling out for all languages, but then you're investing in, rolling out for all subject materials.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S05","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":5,"global_order":337,"speaker":"ARAN","english_text":"So you want to get to a stage where people subscribe to the school because you subscribe to school obviously, wherever you are, you want access to those things.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S06","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":6,"global_order":338,"speaker":"TOM","english_text":"A Full-Stack Remote-School","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S07","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":7,"global_order":339,"speaker":"ARAN","english_text":"Completely - and you've reinvested so much that you've got such a full-stack thing going on that it's very hard for people to come and attack that and then you're adding on top of that, you're going out into the social stuff but then also, there's a natural layer there which becomes your entertainment layer.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S08","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":8,"global_order":340,"speaker":"ARAN","english_text":"So you've got somebody who's learned physics with you and they become really good at it.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S09","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":9,"global_order":341,"speaker":"ARAN","english_text":"They're now very interested in physics and they want to be playing in their groups and their subscription is getting them into the various different groups and the social stuff, but they also want to be seeing and learning really interesting new things about physics.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S10","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":10,"global_order":342,"speaker":"ARAN","english_text":"So if there's a terrific physics program on, they're going to want to watch it.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S100","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":100,"global_order":432,"speaker":"TOM","english_text":"And then you start thinking, we've got a 500 million pot, half a billion to do this experiment over a five year period or whatever.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S101","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":101,"global_order":433,"speaker":"TOM","english_text":"That'd be interesting.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S102","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":102,"global_order":434,"speaker":"TOM","english_text":"It doesn't have to be all your own money.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S103","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":103,"global_order":435,"speaker":"TOM","english_text":"If you're putting enough of your own money to signal and to get that awareness, then I think other people would follow probably.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S104","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":104,"global_order":436,"speaker":"ARAN","english_text":"And you could probably turn some arms, politically speaking and tap into some sources of money that would otherwise be frittered away, as long as you're careful about not making it too obvious that you're going to be undermining those systems at the same time.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S105","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":105,"global_order":437,"speaker":"ARAN","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S106","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":106,"global_order":438,"speaker":"ARAN","english_text":"Also there's some need for care there if you're looking at establishing a currency, then you want to be retaining control over the production of that currency.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S107","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":107,"global_order":439,"speaker":"ARAN","english_text":"So if you end up ceding control on that, you might discover, Oh, I accidentally got into bed with a crocodile and now some stuff is happening.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S108","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":108,"global_order":440,"speaker":"ARAN","english_text":"I don't like.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S109","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":109,"global_order":441,"speaker":"ARAN","english_text":"Yeah, but I do think, if you build an education layer that works and a social layer that works...","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S11","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":11,"global_order":343,"speaker":"ARAN","english_text":"So you start producing those terrific physics programs...","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S110","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":110,"global_order":442,"speaker":"ARAN","english_text":"how many regular daily users does Facebook have?","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S111","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":111,"global_order":443,"speaker":"ARAN","english_text":"It's two and a half billion, isn't it?","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S112","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":112,"global_order":444,"speaker":"ARAN","english_text":"And it's shite.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S113","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":113,"global_order":445,"speaker":"ARAN","english_text":"It just destroys your life.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S114","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":114,"global_order":446,"speaker":"ARAN","english_text":"It's rubbish.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S115","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":115,"global_order":447,"speaker":"ARAN","english_text":"But they've got two and a half billion users.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S116","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":116,"global_order":448,"speaker":"ARAN","english_text":"So if you say, we're going to be charging for that.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S117","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":117,"global_order":449,"speaker":"ARAN","english_text":"But we're not just magically saying now, you've got to pay- we're growing it as a paid-for thing.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S118","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":118,"global_order":450,"speaker":"ARAN","english_text":"So is there a reason we can't get two to half what Facebook has done?","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S119","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":119,"global_order":451,"speaker":"ARAN","english_text":"So Facebook, when it's something really good and you enjoy it and you want it and you pay for it because it's a value proposition to begin with.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S12","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":12,"global_order":344,"speaker":"ARAN","english_text":"with language learners, they benefit and continue to increase their mastery by engaging in media in the target language.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S120","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":120,"global_order":452,"speaker":"ARAN","english_text":"Facebook had to say, this is a new thing - online - and you're used to online things being free, but learning a language, nobody expects that to be for free.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S121","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":121,"global_order":453,"speaker":"ARAN","english_text":"So you're paying for it from the start.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S122","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":122,"global_order":454,"speaker":"ARAN","english_text":"I see no reason why we shouldn't get to, a billion users and then you've got a hundred billion a year coming in and then you can f all sorts of interesting things.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S123","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":123,"global_order":455,"speaker":"ARAN","english_text":"Which will be fun, too much fun.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S124","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":124,"global_order":456,"speaker":"ARAN","english_text":"But also, I don't think you need to get there to trigger an ignition event.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S125","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":125,"global_order":457,"speaker":"ARAN","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S126","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":126,"global_order":458,"speaker":"ARAN","english_text":"I think that we can probably do that.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S127","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":127,"global_order":459,"speaker":"ARAN","english_text":"I think we'll probably do it with really tiny amounts of money...","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S128","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":128,"global_order":460,"speaker":"ARAN","english_text":"one of the things about currency, I think is that you're starting from the concept of, we want to be an escape pod for you.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S129","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":129,"global_order":461,"speaker":"ARAN","english_text":"So we want this to be a basic income.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S13","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":13,"global_order":345,"speaker":"ARAN","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S130","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":130,"global_order":462,"speaker":"ARAN","english_text":"We want this to be something that allows you not to work, but we don't have to start there because people don't expect that from a currency so if we say, look, we're going to give you a hundred quid a month.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S131","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":131,"global_order":463,"speaker":"ARAN","english_text":"We're just going to give it to you.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S132","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":132,"global_order":464,"speaker":"ARAN","english_text":"So if we start with, say we've got a hundred thousand to put in...","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S133","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":133,"global_order":465,"speaker":"ARAN","english_text":"At this point we got interrupted by the dog.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S134","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":134,"global_order":466,"speaker":"ARAN","english_text":"We're going to crack on with this after the next lockdown...","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S14","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":14,"global_order":346,"speaker":"ARAN","english_text":"So you make that media, you make it interesting.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S15","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":15,"global_order":347,"speaker":"ARAN","english_text":"You're also controlling for positive information flow.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S16","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":16,"global_order":348,"speaker":"ARAN","english_text":"So you're taking people away from hate groups and stuff - so fundamentally, if we've taught English successfully to somebody and we've started to provide them more and more content about that, then we have a first mover advantage on Netflix.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S17","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":17,"global_order":349,"speaker":"ARAN","english_text":"Because they have to decide that they want to stop our subscription and then start the Netflix subscription.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S18","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":18,"global_order":350,"speaker":"ARAN","english_text":"And our subscription has got massive investment in content, but it's also always thinking carefully about how do you make that effectively available for non fluent people?","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S19","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":19,"global_order":351,"speaker":"ARAN","english_text":"So they've always got the stepladder into it, which Netflix have tried to do some stuff with subtitling, which is the wrong solution and won't work.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S20","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":20,"global_order":352,"speaker":"ARAN","english_text":"So you've then got a situation, what you'll have inevitably is that some of them will go to Netflix.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S21","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":21,"global_order":353,"speaker":"TOM","english_text":"Is your stuff going to be English content, but then with different target, different starting languages, is that the idea?","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S22","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":22,"global_order":354,"speaker":"TOM","english_text":"You're going to have multi content?","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S23","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":23,"global_order":355,"speaker":"ARAN","english_text":"So I think it's multilanguage content, but for somebody who's learning English, it's English language content, but we have different ways in which that is made more accessible to them.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S24","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":24,"global_order":356,"speaker":"ARAN","english_text":"Some of which is about transcripts rather than subtitles, which is a really important distinction.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S25","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":25,"global_order":357,"speaker":"ARAN","english_text":"So they can read a transcript in advance and then they listen to it without the subtitles.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S26","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":26,"global_order":358,"speaker":"ARAN","english_text":"but also Condensations Synopses, listening exercises and netflix isn't taking on any of that stuff, but we grow up with that.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S27","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":27,"global_order":359,"speaker":"ARAN","english_text":"So I think if we get it right, that we end up the Netflix for non first-language, English speakers, but we also very easily obviously go and become the Netflix for people who speak other languages.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S28","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":28,"global_order":360,"speaker":"ARAN","english_text":"Lots of them.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S29","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":29,"global_order":361,"speaker":"ARAN","english_text":"So we start to be a, we start to be a, a Netflix for, maybe being a Netflix for Mandarin is going to be challenging because of course - the communist party really gets it.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S30","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":30,"global_order":362,"speaker":"ARAN","english_text":"They know that this stuff matters.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S31","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":31,"global_order":363,"speaker":"ARAN","english_text":"They know that these are the channels of communications.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S32","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":32,"global_order":364,"speaker":"ARAN","english_text":"They don't want you to have them.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S33","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":33,"global_order":365,"speaker":"ARAN","english_text":"But maybe we become the Netflix for Hindi.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S34","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":34,"global_order":366,"speaker":"ARAN","english_text":"But also for, Swahili so if you've got them in an environment where they're 'ooh!","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S35","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":35,"global_order":367,"speaker":"ARAN","english_text":"we can watch these things, but sometimes actually we'd like to be watching something Mandarin, oh you offer that as well?","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S36","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":36,"global_order":368,"speaker":"ARAN","english_text":"Fantastic!'","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S37","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":37,"global_order":369,"speaker":"TOM","english_text":"Okay.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S38","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":38,"global_order":370,"speaker":"TOM","english_text":"So I was thinking the Netflix layer of content would be in target language for learners.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S39","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":39,"global_order":371,"speaker":"TOM","english_text":"So it's Mandarin for everyone who's learning Mandarin.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S40","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":40,"global_order":372,"speaker":"TOM","english_text":"You're thinking of first language, Mandarin speakers who wants to...","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S41","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":41,"global_order":373,"speaker":"TOM","english_text":"okay.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S42","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":42,"global_order":374,"speaker":"ARAN","english_text":"We're already getting towards that with Welsh, we're not all that far away, from a point where it's going to be worthwhile for people to subscribe to us, to be able to get the content that we're producing in Welsh, because we're starting to commission some Welsh writers to produce stuff for us.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S43","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":43,"global_order":375,"speaker":"ARAN","english_text":"And we make sure that's all with the steps to make it more accessible for learners.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S44","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":44,"global_order":376,"speaker":"ARAN","english_text":"But it also is interesting, good content - has to be - they don't want rubbish content that they have a helping him to get to it, it needs to be good.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S45","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":45,"global_order":377,"speaker":"TOM","english_text":"And by the time they get good enough, then they are equivalent to native speakers in terms of their ability to actually engage in media and watch media.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S46","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":46,"global_order":378,"speaker":"TOM","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S47","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":47,"global_order":379,"speaker":"TOM","english_text":"Consume.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S48","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":48,"global_order":380,"speaker":"TOM","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S49","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":49,"global_order":381,"speaker":"TOM","english_text":"consume the media.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S50","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":50,"global_order":382,"speaker":"TOM","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S51","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":51,"global_order":383,"speaker":"ARAN","english_text":"Okay, so you get to the stage where you've done the education layer and you've got the entertainment layer and I very strongly suspect that if you're solving for all language learners, then it becomes extraordinary difficult for Netflix really to withstand that.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S52","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":52,"global_order":384,"speaker":"ARAN","english_text":"It might be that you end up doing a kind of partnership thing there even...","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S53","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":53,"global_order":385,"speaker":"TOM","english_text":"anyway, what's it for Netflix?","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S54","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":54,"global_order":386,"speaker":"TOM","english_text":"Really?","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S55","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":55,"global_order":387,"speaker":"TOM","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S56","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":56,"global_order":388,"speaker":"TOM","english_text":"yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S57","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":57,"global_order":389,"speaker":"TOM","english_text":"Oh, it's all right.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S58","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":58,"global_order":390,"speaker":"ARAN","english_text":"I think it's, I think it's really good - but I don't want to spend my time watching a screen.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S59","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":59,"global_order":391,"speaker":"ARAN","english_text":"So it's always going to be running into that headwind of people thinking, God, I just wasted my day.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S60","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":60,"global_order":392,"speaker":"ARAN","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S61","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":61,"global_order":393,"speaker":"ARAN","english_text":"So, if you're education plus entertainment, then I've got all this value.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S62","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":62,"global_order":394,"speaker":"ARAN","english_text":"And then I did a little bit of entertainment and that was okay.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S63","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":63,"global_order":395,"speaker":"ARAN","english_text":"and","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S64","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":64,"global_order":396,"speaker":"TOM","english_text":"if this is all stimulating your meetups Maybe it's schools that don't have a future and universities extend for all ages and schools and universities merge and schools become outreach.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S65","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":65,"global_order":397,"speaker":"TOM","english_text":"Schools become affiliated to universities and just reach down and into communities - then what we're doing is we're providing all the content and making it super- amazing, super- free, not free, but super cheap.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S66","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":66,"global_order":398,"speaker":"TOM","english_text":"And then stimulating the meetup side of things, the connection, the collaboration, the learning groups.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S67","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":67,"global_order":399,"speaker":"ARAN","english_text":"And then with the content stuff, you're basically you're storytelling.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S68","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":68,"global_order":400,"speaker":"ARAN","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.803209+00","updated_at":"2026-10-20 22:40:23.803209+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S69","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":69,"global_order":401,"speaker":"ARAN","english_text":"So, and this kind of is a factor in - you can hear fascists screaming about it in America, that all their content producers by and large, have really liberal mindsets.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S70","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":70,"global_order":402,"speaker":"ARAN","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S71","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":71,"global_order":403,"speaker":"ARAN","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S72","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":72,"global_order":404,"speaker":"ARAN","english_text":"Cause it's just hard to write a script, encouraging people to hate other people.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S73","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":73,"global_order":405,"speaker":"ARAN","english_text":"Makes you look a bit shitty and really you do that stuff behind closed doors.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S74","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":74,"global_order":406,"speaker":"ARAN","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S75","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":75,"global_order":407,"speaker":"ARAN","english_text":"So getting it out there and then discovering that everybody hates it.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S76","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":76,"global_order":408,"speaker":"ARAN","english_text":"So no, content, I think naturally storytelling is such a human activity.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S77","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":77,"global_order":409,"speaker":"ARAN","english_text":"It curves towards being kind to humans.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S78","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":78,"global_order":410,"speaker":"ARAN","english_text":"So then you're just pumping a lot of positivity into the world and I think at roundabout that stage, if you're thinking: every language, through the medium of all these other languages and all other types of knowledge, factual based acquisition and social groupings and an entertainment layer, you've gotta be prepared to spend a fair amount of time throwing the initial capital back at building that out.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S79","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":79,"global_order":411,"speaker":"ARAN","english_text":"and then I think possibly it would be legitimate for us to think in terms of 5% of turnover goes into test projects - and then that number can start to come up as we start to hit levels of achievement with layer building.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S80","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":80,"global_order":412,"speaker":"ARAN","english_text":"So if we get to the stage where we've built the layers, we've got insane amounts of capital coming in now, that, then yeah, we can put 50% insane amounts of capital back into building more, 50% now into triggering projects.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S81","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":81,"global_order":413,"speaker":"ARAN","english_text":"So I think we've got to be a little bit careful about just not going too fast too soon on the project side of things, it's gotta be a hundred percent reinvestment for growth.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S82","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":82,"global_order":414,"speaker":"ARAN","english_text":"But if we, we get to the stage where we've got a billion a year coming in, then, you stick 50 million a year into a project.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S83","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":83,"global_order":415,"speaker":"ARAN","english_text":"That's just not going to be slowing you down at all.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S84","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":84,"global_order":416,"speaker":"ARAN","english_text":"And that's clearly going to give you some chances to trigger some interesting stuff.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S85","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":85,"global_order":417,"speaker":"TOM","english_text":"So the other thing you could do as well as you could use your leverage and cash to attract other people's cash.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S86","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":86,"global_order":418,"speaker":"TOM","english_text":"Because there are a lot of people by then - in the next 5, 10, 15 years, there's lots of people that probably want to do useful things with their money - the Bill Gates, the Buffets, people like that, who's the guy recently gave away something like 8 billion?","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S87","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":87,"global_order":419,"speaker":"TOM","english_text":"He's given away an awful lot of money and he's managed to do it in his lifetime.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S88","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":88,"global_order":420,"speaker":"TOM","english_text":"So he's now basically poor.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S89","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":89,"global_order":421,"speaker":"TOM","english_text":"He's got rid of his last money.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S90","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":90,"global_order":422,"speaker":"TOM","english_text":"He's closed his foundation.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S91","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":91,"global_order":423,"speaker":"TOM","english_text":"He has his apartment in New York and he has a very modest life and he's given away something of the order of 8 billion, I think, in his lifetime.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S92","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":92,"global_order":424,"speaker":"TOM","english_text":"But given away everything.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S93","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":93,"global_order":425,"speaker":"TOM","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S94","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":94,"global_order":426,"speaker":"TOM","english_text":"With a view to say, it's much more enjoyable for me to be able to give this away in real time and be able to actually see it, and if I'm giving it away, why give it away to foundation?","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S95","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":95,"global_order":427,"speaker":"TOM","english_text":"Just give it away.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S96","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":96,"global_order":428,"speaker":"TOM","english_text":"But people are increasingly going to want to do that.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S97","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":97,"global_order":429,"speaker":"TOM","english_text":"So if you say that you're going to fund things like universal basic income experiments, You could get large philanthropists to get on board.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S98","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":98,"global_order":430,"speaker":"TOM","english_text":"And then say: we're going to put 50 million into this project, what we're looking for is another top philanthropist to put 50 million each - it's chicken feed for them.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"talk-bollocks-4:SC06-S99","pod_slug":"talk-bollocks-4","scene_number":6,"scene_label":"Chapter 6","scene_title":"But First Let's Create The Education Layer","scene_subtitle":null,"difficulty":null,"sentence_number":99,"global_order":431,"speaker":"TOM","english_text":"Yeah.","author_notes":null,"created_at":"2026-10-20 22:40:23.882202+00","updated_at":"2026-10-20 22:40:23.882202+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null}]$tbr$);
